package com.nexusdrive.common.util;
import java.nio.charset.StandardCharsets; import java.security.*; import java.util.*;
public class ConsistentHashingUtil { private final NavigableMap<Long,String> ring=new TreeMap<>(); private final int replicas; public ConsistentHashingUtil(Collection<String> nodes){this(nodes,128);} public ConsistentHashingUtil(Collection<String> nodes,int replicas){if(nodes==null||nodes.isEmpty())throw new IllegalArgumentException("At least one node required");this.replicas=replicas;nodes.forEach(this::addNode);} public synchronized void addNode(String node){for(int i=0;i<replicas;i++)ring.put(hash(node+'#'+i),node);} public synchronized void removeNode(String node){ring.entrySet().removeIf(e->e.getValue().equals(node));} public synchronized String getNode(String key){if(ring.isEmpty())throw new IllegalStateException("No storage nodes");var e=ring.ceilingEntry(hash(key));return(e==null?ring.firstEntry():e).getValue();} private long hash(String s){try{byte[] b=MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));return ((long)(b[0]&255)<<56)|((long)(b[1]&255)<<48)|((long)(b[2]&255)<<40)|((long)(b[3]&255)<<32)|((long)(b[4]&255)<<24)|((long)(b[5]&255)<<16)|((long)(b[6]&255)<<8)|(b[7]&255L);}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}} }
